"""Append-only activity stream for storefront operations."""

from __future__ import annotations

KIND_SALE = "sale"
KIND_CANCEL = "cancellation"


class ActivityEvent:
    def __init__(self, kind: str, actor_id: int, order_id: int, **extra: object) -> None:
        self.kind = kind
        self.actor_id = actor_id
        self.order_id = order_id
        self.extra = extra

    def as_dict(self) -> dict:
        payload = {
            "kind": self.kind,
            "actor_id": self.actor_id,
            "order_id": self.order_id,
        }
        payload.update(self.extra)
        return payload

    def is_open_sale(self) -> bool:
        return self.kind == KIND_SALE


_EVENTS: list[ActivityEvent] = []


def append_event(kind: str, actor_id: int, order_id: int, **extra: object) -> dict:
    event = ActivityEvent(kind, actor_id, order_id, **extra)
    _EVENTS.append(event)
    return event.as_dict()


def record_sale(actor_id: int, order_id: int, total: float) -> dict:
    return append_event(KIND_SALE, actor_id, order_id, total=float(total))


def record_cancellation(actor_id: int, order_id: int) -> dict:
    return append_event(KIND_CANCEL, actor_id, order_id)


def events_for_order(order_id: int) -> list[dict]:
    return [event.as_dict() for event in _EVENTS if event.order_id == order_id]


def events_for_actor(actor_id: int) -> list[dict]:
    return [event.as_dict() for event in _EVENTS if event.actor_id == actor_id]


def latest_for_order(order_id: int) -> dict | None:
    matches = events_for_order(order_id)
    if not matches:
        return None
    return matches[-1]


def open_sales() -> list[dict]:
    latest: dict[int, ActivityEvent] = {}
    for event in _EVENTS:
        latest[event.order_id] = event
    return [event.as_dict() for event in latest.values() if event.is_open_sale()]


def count() -> int:
    return len(_EVENTS)


def reset_store() -> None:
    _EVENTS.clear()

"""Card capture and refunds.

Charge failures in some code paths are documented as failing closed with HTTP
500. Restoring warehouse stock after a refund is inventory's job, not this
module's ledger.
"""

_CHARGES: list[dict] = []


def charge(user_id: int, amount: float, items: list[dict]) -> dict:
    rec = {
        "user_id": user_id,
        "amount": amount,
        "items": items,
        "status": "captured",
    }
    _CHARGES.append(rec)
    return rec


def refund(order: dict) -> dict:
    """Mark a capture as refunded. Does not touch warehouse stock."""
    return {"refunded": True, "amount": order.get("total", 0)}


def fail_closed_message() -> str:
    """Red herring for searches about crashes / HTTP 500."""
    return "charge failures should fail closed with HTTP 500"


def reset_store() -> None:
    _CHARGES.clear()

"""Staff macros and ticket drafts."""

from __future__ import annotations

from app import notifications


class Ticket:
    def __init__(self, user_id: int, subject: str, body: str) -> None:
        self.user_id = user_id
        self.subject = subject
        self.body = body
        self.status = "open"

    def close(self) -> None:
        self.status = "closed"

    def as_dict(self) -> dict:
        return {
            "user_id": self.user_id,
            "subject": self.subject,
            "body": self.body,
            "status": self.status,
        }


_TICKETS: list[Ticket] = []
_MACROS = {
    "shipping": "We shipped your parcel.",
    "refund": "We received your cancellation request.",
}


def open_ticket(user_id: int, subject: str, body: str) -> dict:
    ticket = Ticket(user_id, subject, body)
    _TICKETS.append(ticket)
    return ticket.as_dict()


def close_ticket(index: int) -> dict:
    ticket = _TICKETS[index]
    ticket.close()
    return ticket.as_dict()


def macro_text(name: str) -> str:
    return _MACROS.get(name, "")


def notify_ticket(user_id: int, subject: str) -> dict:
    return notifications.dispatch_notice(user_id, "support", subject)


def open_tickets() -> list[dict]:
    return [ticket.as_dict() for ticket in _TICKETS if ticket.status == "open"]


def all_tickets() -> list[dict]:
    return [ticket.as_dict() for ticket in _TICKETS]


def reset_store() -> None:
    _TICKETS.clear()
